const data=window.portfolio;
const projectRoot=document.querySelector('#projects');
function render(filter='all'){projectRoot.innerHTML=data.projects.filter(p=>filter==='all'||p.status===filter).map(p=>`<button class="project-card ${p.color}" data-project="${p.id}" aria-label="Read about ${p.title}"><div class="card-top"><span>${p.category}</span><span class="status">${p.status==='progress'?'In progress':'Completed'}</span></div><div class="project-art" aria-hidden="true"><span class="artifact">${p.motif}</span><span class="art-note">${p.subtitle}</span><span class="corner">№ ${p.index}</span></div><div class="card-body"><div><h3>${p.title}</h3><p>${p.description}</p></div><span class="project-open" aria-hidden="true">↗</span></div><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div></button>`).join('');}render();
document.querySelector('#skills').innerHTML=data.skills.map(s=>`<div><h4>${s.title}</h4><div>${s.items.map(i=>`<span>${i}</span>`).join('')}</div></div>`).join('');
if(document.querySelector('#leadership'))document.querySelector('#leadership').innerHTML=data.leadership.map(s=>`<div><span>${s.place}</span><h4>${s.role}</h4>${s.note?`<p>${s.note}</p>`:''}</div>`).join('');
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});render(b.dataset.filter)}));
const dialog=document.querySelector('#detail');let opener;
projectRoot.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;opener=b;const p=data.projects.find(x=>x.id===b.dataset.project);document.querySelector('#detail-content').innerHTML=`<span class="tag ${p.color}">${p.status==='progress'?'In progress':'Completed'}</span><p class="eyebrow">${p.category}</p><h2>${p.title}</h2><p class="detail-intro">${p.subtitle}</p><p>${p.description}</p><h3>Inside the project</h3><p>${p.details}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>`;dialog.showModal();document.querySelector('#close-detail').focus()});
document.querySelector('#close-detail').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>opener?.focus());
const notes={book:['A place for words, stories and a little imagination.','I’m drawn to books and poetry — words that invite me to pause, imagine and look again.'],coffee:['Curious about new corners, café tables and the stories in between.','A tiny pause: take a breath, let an idea settle, and notice something around you.'],record:['A small soundtrack to everyday curiosity.','The vinyl is spinning. A visual toy, with no audio playback.']};
function toggleToy(id){const b=document.querySelector(`[data-toy="${id}"]`);const active=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',active);b.classList.toggle('playing',active);b.setAttribute('aria-label',id==='book'?(active?'Close the book':'Open the book'):id==='coffee'?(active?'Close the coffee cup lid':'Open the coffee cup lid'):(active?'Stop the vinyl, visual animation only':'Spin the vinyl, visual animation only'));document.querySelector(`#${id}-note`).textContent=notes[id][+active];const trigger=document.querySelector(`[data-trigger="${id}"]`);trigger.textContent=id==='record'?(active?'Stop the vinyl −':'Spin the vinyl +'):id==='book'?(active?'Close the book −':'Open the book +'):(active?'Close the lid −':'Open the lid +');}document.querySelectorAll('[data-toy]').forEach(b=>b.onclick=()=>toggleToy(b.dataset.toy));document.querySelectorAll('[data-trigger]').forEach(b=>b.onclick=()=>toggleToy(b.dataset.trigger));
const observer=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>{const yes=a.getAttribute('href')==='#'+e.target.id;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}})},{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));
